using Pharma.Bll;
using Pharma.Models;

namespace Pharma.Ui;

public sealed class UC_Administration : UserControl
{
    private readonly Utilisateur _user; private readonly GestionCaisseService _caisse; private readonly ParametresService _parametres; private readonly SauvegardeService _sauvegarde;
    private readonly NumericUpDown _fond=new(){Minimum=0,Maximum=100000000,DecimalPlaces=2,ThousandsSeparator=true};
    private readonly NumericUpDown _compte=new(){Minimum=0,Maximum=100000000,DecimalPlaces=2,ThousandsSeparator=true}; private readonly TextBox _justification=new(){Dock=DockStyle.Fill}; private readonly Label _resume=new(){Dock=DockStyle.Fill,AutoSize=false};
    private readonly TextBox _nom=new(),_telephone=new(),_adresse=new(),_email=new(),_devise=new(); private readonly NumericUpDown _seuilAlerte=new(){Minimum=0,Maximum=365,Value=90}; private readonly DateTimePicker _heure=new(){Format=DateTimePickerFormat.Time,ShowUpDown=true};
    public UC_Administration(Utilisateur user,GestionCaisseService caisse,ParametresService parametres,SauvegardeService sauvegarde){_user=user;_caisse=caisse;_parametres=parametres;_sauvegarde=sauvegarde;Dock=DockStyle.Fill;BackColor=Color.FromArgb(244,247,250);Construire();ChargerParametres();}
    private void Construire()
    {
        var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2};root.RowStyles.Add(new RowStyle(SizeType.Absolute,48));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.Controls.Add(new Label{Text="Administration",Dock=DockStyle.Fill,Font=new Font("Segoe UI Semibold",19,FontStyle.Bold),ForeColor=UiTheme.Navy,TextAlign=ContentAlignment.MiddleLeft},0,0);
        var tabs=new TabControl{Dock=DockStyle.Fill};tabs.TabPages.Add(ConstruireCaisse());tabs.TabPages.Add(ConstruireSauvegarde());tabs.TabPages.Add(ConstruireParametres());root.Controls.Add(tabs,0,1);Controls.Add(root);
    }
    private TabPage ConstruireCaisse(){var page=new TabPage("Clôture de caisse");var l=new TableLayoutPanel{Dock=DockStyle.Top,Height=300,Padding=new Padding(18),ColumnCount=2,RowCount=8};l.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,230));l.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));for(int i=0;i<6;i++)l.RowStyles.Add(new RowStyle(SizeType.Absolute,42));l.RowStyles.Add(new RowStyle(SizeType.Absolute,70));l.RowStyles.Add(new RowStyle(SizeType.Percent,100));Ajouter(l,0,"Fond à l'ouverture",_fond);Ajouter(l,1,"Montant compté",_compte);Ajouter(l,2,"Justification de l'écart",_justification);l.SetRow(_justification,2);var ouvrir=UiTheme.Button("Ouvrir / actualiser");ouvrir.Click+=(_,_)=>ActualiserCaisse();l.Controls.Add(ouvrir,1,3);var cloturer=UiTheme.Button("Clôturer la caisse");cloturer.BackColor=UiTheme.Green;cloturer.Click+=(_,_)=>Cloturer();l.Controls.Add(cloturer,1,4);_resume.Font=new Font("Segoe UI",10);_resume.Padding=new Padding(0,8,0,0);l.Controls.Add(_resume,0,5);l.SetColumnSpan(_resume,2);page.Controls.Add(l);return page;}
    private TabPage ConstruireSauvegarde(){var p=new TabPage("Sauvegarde / restauration");var l=new FlowLayoutPanel{Dock=DockStyle.Top,Height=140,Padding=new Padding(18),WrapContents=true};var save=UiTheme.Button("Sauvegarder maintenant");save.Width=190;save.Click+=(_,_)=>Sauvegarder();var restore=UiTheme.Button("Restaurer une sauvegarde");restore.Width=190;restore.Click+=(_,_)=>Restaurer();l.Controls.Add(save);l.Controls.Add(restore);l.Controls.Add(new Label{Text="La restauration crée d'abord une copie de sécurité de la base actuelle.",AutoSize=true,Padding=new Padding(0,12,0,0),ForeColor=Color.FromArgb(92,104,116)});p.Controls.Add(l);return p;}
    private TabPage ConstruireParametres(){var p=new TabPage("Paramètres pharmacie");var l=new TableLayoutPanel{Dock=DockStyle.Top,Height=340,Padding=new Padding(18),ColumnCount=2,RowCount=8};l.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,230));l.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));for(int i=0;i<7;i++)l.RowStyles.Add(new RowStyle(SizeType.Absolute,42));Ajouter(l,0,"Nom de la pharmacie",_nom);Ajouter(l,1,"Téléphone",_telephone);Ajouter(l,2,"Adresse",_adresse);Ajouter(l,3,"Email",_email);Ajouter(l,4,"Devise",_devise);Ajouter(l,5,"Délai péremption (jours)",_seuilAlerte);_heure.Dock=DockStyle.Fill;Ajouter(l,6,"Heure sauvegarde",_heure);var save=UiTheme.Button("Enregistrer les paramètres");save.Click+=(_,_)=>EnregistrerParametres();l.Controls.Add(save,1,7);p.Controls.Add(l);return p;}
    private static void Ajouter(TableLayoutPanel l,int row,string texte,Control c){l.Controls.Add(new Label{Text=texte,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,ForeColor=UiTheme.Navy},0,row);c.Dock=DockStyle.Fill;l.Controls.Add(c,1,row);}
    private void ActualiserCaisse(){try{var s=_caisse.ObtenirOuOuvrir(_user.Id,_fond.Value);var r=_caisse.Calculer(s.Id);_resume.Text=$"Session {s.Id}\nEspèces ventes : {r.EspecesVentes:N2}\nCarte : {r.VentesCarte:N2}    Mobile : {r.VentesMobile:N2}\nMouvements : +{r.Entrees:N2} / -{r.Sorties:N2}\nMontant attendu : {r.Attendu:N2}";}catch(Exception ex){MessageBox.Show(ex.Message,"Caisse",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
    private void Cloturer(){try{var s=_caisse.ObtenirOuOuvrir(_user.Id,_fond.Value);var r=_caisse.Cloturer(s.Id,_user.Id,_compte.Value,_justification.Text);MessageBox.Show($"Caisse clôturée. Écart : {r.Ecart:N2}","Clôture",MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){MessageBox.Show(ex.Message,"Clôture impossible",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
    private void Sauvegarder(){using var d=new SaveFileDialog{Filter="Base SQLite (*.db)|*.db",FileName=$"pharma-{DateTime.Now:yyyyMMdd-HHmmss}.db"};if(d.ShowDialog(FindForm())!=DialogResult.OK)return;try{_sauvegarde.Sauvegarder(d.FileName,_user);MessageBox.Show("Sauvegarde terminée.","Sauvegarde",MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){MessageBox.Show(ex.Message,"Sauvegarde impossible",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
    private void Restaurer(){using var d=new OpenFileDialog{Filter="Base SQLite (*.db)|*.db"};if(d.ShowDialog(FindForm())!=DialogResult.OK)return;if(MessageBox.Show("La base actuelle sera copiée avant restauration. Continuer ?","Confirmation",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;try{var copie=_sauvegarde.Restaurer(d.FileName,_user);MessageBox.Show($"Restauration terminée. Copie de sécurité :\n{copie}","Restauration",MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){MessageBox.Show(ex.Message,"Restauration impossible",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
    private void ChargerParametres(){var p=_parametres.LireTout();_nom.Text=p.GetValueOrDefault("NomPharmacie","");_telephone.Text=p.GetValueOrDefault("Telephone","");_adresse.Text=p.GetValueOrDefault("Adresse","");_email.Text=p.GetValueOrDefault("Email","");_devise.Text=p.GetValueOrDefault("Devise","FCFA");_seuilAlerte.Value=int.TryParse(p.GetValueOrDefault("DelaiPeremptionJours","90"),out var s)?Math.Clamp(s,0,365):90;_heure.Value=TimeSpan.TryParse(p.GetValueOrDefault("HeureSauvegarde","22:00"),out var h)?DateTime.Today.Add(h):DateTime.Today.AddHours(22);}
    private void EnregistrerParametres(){try{_parametres.Enregistrer(_user,new Dictionary<string,string>{{"NomPharmacie",_nom.Text.Trim()},{"Telephone",_telephone.Text.Trim()},{"Adresse",_adresse.Text.Trim()},{"Email",_email.Text.Trim()},{"Devise",_devise.Text.Trim()},{"DelaiPeremptionJours",_seuilAlerte.Value.ToString()},{"HeureSauvegarde",_heure.Value.ToString("HH:mm")}});MessageBox.Show("Paramètres enregistrés.","Paramètres",MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){MessageBox.Show(ex.Message,"Enregistrement impossible",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
}
